"""The group generated by g1, g2 (SL_2(29), order 24,360) and its elements modulo +-1.
g1, g2 が生成する群（SL_2(29)、位数 24,360）と、±1 を法とした元。

All elements are enumerated by breadth-first search from the identity, multiplying by
the generators on the right, in exact int64 arithmetic. The search stops when no new
element appears, so the result is closed under multiplication by g1, g2 and hence is
the whole generated group (a finite set closed under right multiplication by the
generators of a finite group is the group).
単位元から生成元を右から掛ける幅優先探索で、全元を int64 の厳密な演算で列挙する。新しい元が出なくなったら止める。
結果は g1, g2 の右からの積で閉じているので、生成される群全体になる（有限群では、生成元の右からの積で閉じた空でない部分集合は群全体）。

The order of enumeration is deterministic, so element indices are reproducible.
列挙の順序は決定的なので、元の番号は再現できる。
"""
import numpy as np

from . import exact

ORDER = 24360          # |SL_2(29)| = 29 (29^2 - 1)
ORDER_MOD_SIGN = 12180  # |SL_2(29) / {+-1}|


def enumerate_group(gens, max_order=10 ** 6):
    """All elements of the group generated by `gens` (list of int64 n x n matrices).
    Returns an int16 array (order, n, n) (entries are asserted to fit); element 0 is the identity.
    Products are computed in int64 with an overflow guard.
    `gens` が生成する群の全元。int16 の配列 (位数, n, n) で返す（成分が収まることを確かめる）。0 番は単位元。
    積はオーバーフローを確かめて int64 で計算する。"""
    n = gens[0].shape[0]
    gens = [np.asarray(h, dtype=np.int64) for h in gens]
    identity = np.eye(n, dtype=np.int16)
    seen = {identity.tobytes()}
    elements = [identity]
    frontier = [identity]
    while frontier:
        new = []
        for g in frontier:
            for h in gens:
                x = exact.i64_matmul(g, h)
                assert np.abs(x).max() < 2 ** 15
                x = x.astype(np.int16)
                k = x.tobytes()
                if k not in seen:
                    seen.add(k)
                    elements.append(x)
                    new.append(x)
                    if len(elements) > max_order:
                        raise RuntimeError("group larger than expected")
        frontier = new
    return np.stack(elements)


def sign_normalize(g):
    """The one of +-g whose first nonzero entry (row-major) is positive.
    ±g のうち、最初の 0 でない成分（行優先）が正のもの。"""
    flat = g.ravel()
    i = np.flatnonzero(flat)[0]
    return g if flat[i] > 0 else -g


def elements_mod_sign(E):
    """From the full group E (which must contain -I), one element of each pair {g, -g},
    namely the sign-normalized one, in order of first appearance.
    -I を含む群 E から、各組 {g, -g} の代表（符号を正規化したもの）を、最初に現れた順に 1 つずつ取る。"""
    n = E.shape[1]
    minus_one = -np.eye(n, dtype=E.dtype)
    assert any((g == minus_one).all() for g in E), "-I is not in the group"
    out, taken = [], set()
    for g in E:
        h = sign_normalize(g)
        k = h.tobytes()
        if k not in taken:
            taken.add(k)
            out.append(h)
    return np.stack(out)


def sl2_29_mod_sign(gens):
    """The 12,180 elements of <g1, g2>/{+-1} as an int16 array (12180, 56, 56),
    after checking |<g1, g2>| = 24,360 and -I in <g1, g2>.
    <g1, g2>/{±1} の 12,180 元（int16 の配列）。|<g1, g2>| = 24,360 と -I ∈ <g1, g2> を確かめてから返す。"""
    E = enumerate_group(list(gens))
    assert len(E) == ORDER, f"group order {len(E)}, expected {ORDER}"
    S = elements_mod_sign(E)
    assert len(S) == ORDER_MOD_SIGN
    return S.astype(np.int16)


def inverse_isometry(g, G, Ginv):
    """Inverse of an isometry g of the Gram matrix G: g^{-1} = G g^T G^{-1}
    (from g G g^T = G). Ginv must be the exact integer inverse of G (det G = 1).
    Gram 行列 G の等長変換 g の逆元 g^{-1} = G g^T G^{-1}（g G g^T = G から）。Ginv は G の厳密な整数の逆行列（det G = 1）。"""
    M = exact.i64_matmul(exact.i64_matmul(G, g.T), Ginv)
    assert (exact.i64_matmul(g, M) == np.eye(len(G), dtype=np.int64)).all()
    return M
